import{_ as t,o as e,c as r,ag as o}from"./chunks/framework.DMXcdKmJ.js";const T=JSON.parse('{"title":"接入 HTTP 并映射响应","description":"保存 HTTP 接口、授权发送请求、映射响应数据点，并区分接口配置、调用结果与持续运行。","frontmatter":{"title":"接入 HTTP 并映射响应","description":"保存 HTTP 接口、授权发送请求、映射响应数据点，并区分接口配置、调用结果与持续运行。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/http-outputs.md","filePath":"zh/使用指南/接入HTTP并映射响应.md"}'),n={name:"zh/guide/http-outputs.md"};function s(i,a,p,h,d,l){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="接入-http-并映射响应" tabindex="-1">接入 HTTP 并映射响应 <a class="header-anchor" href="#接入-http-并映射响应" aria-label="Permalink to &quot;接入 HTTP 并映射响应&quot;">​</a></h1><p>入口：<strong>数据中心 → 接入源 → 新建连接 → HTTP</strong>。准备获准的服务地址、方法、参数、认证和响应说明。</p><p><strong>“发送”会实际调用接口。</strong> POST、PUT、DELETE，甚至部分设计不规范的 GET，都可能改变外部业务；练习使用已批准的测试接口，不反复重试生产写入。</p><h2 id="_1-创建接入源与接口" tabindex="-1">1. 创建接入源与接口 <a class="header-anchor" href="#_1-创建接入源与接口" aria-label="Permalink to &quot;1. 创建接入源与接口&quot;">​</a></h2><p>创建 HTTP 接入源后，打开工作台，点击 <strong>“新建接口”</strong>。AI 已保存接口时，先在左侧列表或分组按名称打开，不重复创建。</p><p>填写接口名称、请求地址、方法以及实际需要的参数、请求头和请求体。认证资料通过对应配置维护，不写入公开示例、AI 消息或源码文件。</p><h2 id="_2-保存并核对响应" tabindex="-1">2. 保存并核对响应 <a class="header-anchor" href="#_2-保存并核对响应" aria-label="Permalink to &quot;2. 保存并核对响应&quot;">​</a></h2><p>先核对地址和业务影响，点击 <strong>“保存”</strong>。获准验证时再点击 <strong>“发送”</strong>，检查状态、响应内容和错误，不仅看有没有返回一段 JSON。</p><p>保存接口不等于发送请求成功；一次响应成功也不代表每种参数、业务错误和权限都已验证。</p><p>平台开发环境的网络与浏览器电脑不同，浏览器能访问接口不意味着平台一定能访问。</p><h2 id="_3-映射输出" tabindex="-1">3. 映射输出 <a class="header-anchor" href="#_3-映射输出" aria-label="Permalink to &quot;3. 映射输出&quot;">​</a></h2><p>打开 <strong>“输出映射”</strong>。通常先取得实际响应，再选择完整响应或所需字段，明确类型、名称和取值规则，保存后核对生成的路径。</p><p>例如响应中温度字段的取值是数值时，计算或阈值报警应引用对应数值点，而不是整份响应对象。</p><p>字段缺失、空值或业务失败状态要单独处理，不能把解析失败默认成正常零值。修改输出前也要检查已有引用。</p><h2 id="_4-去哪里查看" tabindex="-1">4. 去哪里查看 <a class="header-anchor" href="#_4-去哪里查看" aria-label="Permalink to &quot;4. 去哪里查看&quot;">​</a></h2><p>接口定义在对应 HTTP 接入源的工作台；输出点在 <strong>“数据中心 → 数据点”</strong>。从点的来源入口返回相同接入源，核对请求与字段。</p><p>页面只展示固定样例，或 AI 只写了一个请求函数，都不能证明平台接口和点已经保存。</p><h2 id="_5-持续调用与正式运行" tabindex="-1">5. 持续调用与正式运行 <a class="header-anchor" href="#_5-持续调用与正式运行" aria-label="Permalink to &quot;5. 持续调用与正式运行&quot;">​</a></h2><p>保存一个接口不会自动证明存在定时请求。需要持续更新时，应确认业务触发、运行引擎、认证有效期和部署中的实际配置。</p><p>让 AI 改造时明确要求“不执行未经授权的外部写请求”，并要求交付接口名、来源和真实输出路径。</p><p>下一步：<a href="/induframe-docs/zh/guide/ai-data-review.html">AI 成果核对</a> · <a href="/induframe-docs/zh/guide/compute-datapoints.html">计算单元</a> · <a href="/induframe-docs/zh/guide/point-alarms.html">报警配置</a>。</p>',21)])])}const u=t(n,[["render",s]]);export{T as __pageData,u as default};
